export const randomPath = (): string => {
  const n = 1 + int(7);
  let s = '';
  for (let i = 0; i < n; i++) s += pick(pathAlphabet);
  return s;
};

// A path likely to match a pattern: replace glob syntax with something it could stand for.
export const instantiate = (pattern: string): string => {
  let s = pattern.replace(/^\.\//, '').replace(/^!+/, '');
  s = s.replace(/\{([^{}]*)\}/g, (_, body: string) => {
    const opts = body.split(',');
    const range = /^(\w)\.\.(\w)$/.exec(body);
    if (range) return pick([range[1] ?? '', range[2] ?? '']);
    return pick(opts);
  });
  s = s.replace(/[@!+*?]\(([^()]*)\)/g, (_, body: string) => pick(body.split('|')));
  s = s.replace(/\[\[:\w+:\]\]/g, () => pick(['a', '1', ' ', '.']));
  s = s.replace(/\[[!^]?([^\]]*)\]/g, (_, body: string) => (body ? pick(Array.from(body)) : 'a'));
  s = s.replace(/\*\*/g, () => pick(['', 'a', 'a/b', '.x', 'x/.y']));
  s = s.replace(/\*/g, () => pick(['', 'a', 'xy', '.z', 'é']));
  s = s.replace(/\?/g, () => pick(['a', '.', 'é', '😀']));
  s = s.replace(/\\(.)/g, '$1');
  return s.replace(/^\/+/, rand() < 0.5 ? '' : '/');
};
